#pragma once

/* Flat node format shared by the host tree builder and CUDA search. */
struct KDNode {
    float bbox_min[3];
    float bbox_max[3];
    int point_idx;
    int axis;
    int left;
    int right;
};

/* GPU ICP correspondence.  Scratch allocations are deliberately persistent. */
#include "solve.h"
#include "kdtree.h"
#include <cuda_runtime.h>
#include <cfloat>

static int *g_match_idx = nullptr;
static double *g_centroid_acc = nullptr;
static double *g_H_acc = nullptr;
static double *g_err_acc = nullptr;
static int g_match_cap = 0;

/* The tree is a median tree, so a fixed, small traversal stack is enough for
   the inputs used here (and avoids both recursion and a per-query allocation). */
__global__ static void kd_nn_kernel(const float *__restrict__ src,
                                    const float *__restrict__ tgt,
                                    const KDNode *__restrict__ nodes,
                                    int N, float limit,
                                    int *__restrict__ matches,
                                    double *__restrict__ sums,
                                    int *__restrict__ count) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= N) return;
    float px=src[3*i], py=src[3*i+1], pz=src[3*i+2];
    float best=limit;
    int bestj=-1;
    int stack[64], sp=0, ni=0;

    while (ni >= 0 || sp) {
        if (ni < 0) ni=stack[--sp];
        const KDNode &n=nodes[ni];
        float x=fmaxf(0.f,fmaxf(n.bbox_min[0]-px,px-n.bbox_max[0]));
        float y=fmaxf(0.f,fmaxf(n.bbox_min[1]-py,py-n.bbox_max[1]));
        float z=fmaxf(0.f,fmaxf(n.bbox_min[2]-pz,pz-n.bbox_max[2]));
        if (x*x+y*y+z*z >= best) { ni=-1; continue; }
        int j=n.point_idx;
        float dx=px-tgt[3*j], dy=py-tgt[3*j+1], dz=pz-tgt[3*j+2];
        float d=dx*dx+dy*dy+dz*dz;
        if (d < best) { best=d; bestj=j; }
        if (n.axis==3) { ni=-1; continue; }
        float v=(n.axis==0?px:(n.axis==1?py:pz));
        float q=tgt[3*j+n.axis];
        int nearc=(v<q)?n.left:n.right;
        int farc =(v<q)?n.right:n.left;
        /* The far branch is deferred.  Bbox tests are repeated when it is
           popped, since best may have improved in the near branch. */
        if (farc>=0) stack[sp++]=farc;
        ni=nearc;
    }
    matches[i]=bestj;
    if (bestj>=0) {
        float qx=tgt[3*bestj], qy=tgt[3*bestj+1], qz=tgt[3*bestj+2];
        atomicAdd(sums+0,(double)px); atomicAdd(sums+1,(double)py);
        atomicAdd(sums+2,(double)pz); atomicAdd(sums+3,(double)qx);
        atomicAdd(sums+4,(double)qy); atomicAdd(sums+5,(double)qz);
        atomicAdd(count,1);
    }
}

__global__ static void centroid_kernel(double *s, const int *count) {
    if (threadIdx.x==0) {
        int n=*count;
        if (n) { double f=1.0/(double)n; for(int k=0;k<6;k++) s[k]*=f; }
        else for(int k=0;k<6;k++) s[k]=0.0;
    }
}

__global__ static void accumulate_kernel(const float *__restrict__ src,
                                         const float *__restrict__ tgt,
                                         const int *__restrict__ matches, int N,
                                         const double *__restrict__ c,
                                         double *__restrict__ H,
                                         double *__restrict__ err) {
    int i=blockIdx.x*blockDim.x+threadIdx.x;
    if(i>=N) return;
    int j=matches[i]; if(j<0) return;
    double px=(double)src[3*i]-c[0], py=(double)src[3*i+1]-c[1], pz=(double)src[3*i+2]-c[2];
    double qx=(double)tgt[3*j]-c[3], qy=(double)tgt[3*j+1]-c[4], qz=(double)tgt[3*j+2]-c[5];
    atomicAdd(H+0,px*qx); atomicAdd(H+1,px*qy); atomicAdd(H+2,px*qz);
    atomicAdd(H+3,py*qx); atomicAdd(H+4,py*qy); atomicAdd(H+5,py*qz);
    atomicAdd(H+6,pz*qx); atomicAdd(H+7,pz*qy); atomicAdd(H+8,pz*qz);
    double dx=(double)src[3*i]-(double)tgt[3*j];
    double dy=(double)src[3*i+1]-(double)tgt[3*j+1];
    double dz=(double)src[3*i+2]-(double)tgt[3*j+2];
    atomicAdd(err,dx*dx+dy*dy+dz*dz);
}

__global__ static void output_kernel(const double *H, const double *e,
                                     float *out, float *err) {
    int t=threadIdx.x;
    if(t<9) out[t]=(float)H[t];
    if(t==9) *err=(float)*e;
}

static void ensure_scratch(int N, cudaStream_t s) {
    if(N>g_match_cap) {
        if(g_match_idx) cudaFree(g_match_idx);
        cudaMalloc(&g_match_idx,(size_t)N*sizeof(int)); g_match_cap=N;
    }
    if(!g_centroid_acc) cudaMalloc(&g_centroid_acc,6*sizeof(double));
    if(!g_H_acc) cudaMalloc(&g_H_acc,9*sizeof(double));
    if(!g_err_acc) cudaMalloc(&g_err_acc,sizeof(double));
    cudaMemsetAsync(g_centroid_acc,0,6*sizeof(double),s);
    cudaMemsetAsync(g_H_acc,0,9*sizeof(double),s);
    cudaMemsetAsync(g_err_acc,0,sizeof(double),s);
}

void icp_correspondence(const float* src,const float* tgt,int N,int M,float d_max,
                        const void* kd_nodes,int n_nodes,float* H_out,float* err_out,
                        int* count_out,cudaStream_t stream) {
    ensure_scratch(N,stream);
    cudaMemsetAsync(count_out,0,sizeof(int),stream);
    int block=256, grid=(N+block-1)/block;
    kd_nn_kernel<<<grid,block,0,stream>>>(src,tgt,(const KDNode*)kd_nodes,N,
                                           d_max*d_max,g_match_idx,g_centroid_acc,count_out);
    centroid_kernel<<<1,32,0,stream>>>(g_centroid_acc,count_out);
    accumulate_kernel<<<grid,block,0,stream>>>(src,tgt,g_match_idx,N,g_centroid_acc,
                                                g_H_acc,g_err_acc);
    output_kernel<<<1,32,0,stream>>>(g_H_acc,g_err_acc,H_out,err_out);
    (void)M; (void)n_nodes;
}
